L134: /**
L135:  * fetchLatestVersion queries npm dist-tags with a timeout. Returns the version
L136:  * string or null on failure.
L137:  */
L138: async function fetchLatestVersion() {
L139:   try {
L140:     const controller = new AbortController();
L141:     const timer = setTimeout(() => controller.abort(), NPM_FETCH_TIMEOUT);
L142:     try {
L143:       const resp = await fetch(NPM_REGISTRY_URL, {
L144:         signal: controller.signal,
L145:         headers: { Accept: "application/json" },
L146:       });
L147:       if (!resp.ok) return null;
L148:       const data = await resp.json();
L149:       return data?.latest ?? null;
L150:     } finally {
L151:       clearTimeout(timer);
L152:     }
L153:   } catch {
L154:     return null;
L155:   }
L156: }
